    [1],
    [0, 2],
    [0, 1, 3],
    [1, 2],
    [1],
  ];

  List<int> topologicalSort(List<List<int>> graph) {
    List<int> sorted = [];
    if (graph.isEmpty || graph[0].isEmpty) return sorted;

    int numVertices = graph.length;
    List<int> outdegrees = List.filled(numVertices, 0);
    List<List<int>> reverse = List.generate(numVertices, (_) => []);

    for (int i = 0; i < numVertices; i++) {
      for (int j = 0; j < graph[i].length; j++) {
        outdegrees[i]++;
        reverse[graph[i][j]].add(i);
      }
    }

    List<int> queue = [];
    for (int i = 0; i < numVertices; i++) {
      if (outdegrees[i] == 0) {
        queue.add(i);
      }
    }

    while (queue.isNotEmpty) {
      int current = queue.removeFirst();
      sorted.add(current);
      for (int neighbor in reverse[current]) {
        outdegrees[neighbor]--;
        if (outdegrees[neighbor] == 0) {
          queue.add(neighbor);
        }
      }
    }

    return sorted;
  }

  List<int> sorted = topologicalSort(graph);
  print('Topological Sort: ${sorted.join(' -> ')}');
}

