    return false;
  }
  int mask = 0;
  for (int r = 0; r < gridWidth; r++) {
    for (int c = 0; c < gridWidth; c++) {
      if (r == row && c == col) {
        mask |= (1 << (r * gridWidth + c));
      }
    }
  }
