int minWordBreak(String s, Set<String> wordDict) {
  if (s.isEmpty) return 0;
  Map<String, int> wordLengths = {};
  for (String word in wordDict) {
    wordLengths[word] = word.length;
  }

  Map<String, int> dp = {};
  for (int i = 0; i <= s.length; i++) {
    dp[i] = s.length + 1;
  }
  dp[0] = 0;

  for (int i = 1; i <= s.length; i++) {
    for (int j = 0; j < i; j++) {
      String sub = s.substring(j, i);
      if (wordLengths.containsKey(sub)) {
        int len = wordLengths[sub]!;
        if (dp[j] != s.length + 1) {
          int cost = len + dp[j];
          dp[i] = dp[i] < cost ? dp[i] : cost;
        }
      }
    }
  }

  return dp[s.length] == s.length + 1 ? 0 : dp[s.length];
}

