      int match = word.substring(i, i + len).compareTo(prefix);
      if (match == 0) {
        dp[prefix][i] = 1;
      } else if (match < 0 && len > 1) {
        int count = longestPrefix[prefix]!;
        dp[prefix][i] = count > dp[prefix][i - len] + 1 ? count : dp[prefix][i - len] + 1;
      }
    }
  }

