      } else if (cmd == 'UNDO') {
        if (out.length > 1) out.removeLast();
      }
    }
    return out;
  }

  for (String cmd in commands) {
    if (cmd == 'BEGIN') {
      history.add('BEGIN');
      stack['BEGIN'] = stack['BEGIN']! + 1;
      totals.add(0);
    } else if (cmd == 'ADD') {
      history.add('ADD');
      stack['ADD'] = stack['ADD']! + 1;
      totals.add(totals.last + stack['BEGIN']!);
    } else if (cmd == 'END') {
      history.add('END');
      stack['END'] = stack['END']! + 1;
      totals.add(totals.last - stack['BEGIN']!);
    } else if (cmd == 'UNDO') {
      history.add('UNDO');
      if (stack['BEGIN']! > 0) stack['BEGIN'] = stack['BEGIN']! - 1;
      if (stack['ADD']! > 0) stack['ADD'] = stack['ADD']! - 1;
      if (stack['END']! > 0) stack['END'] = stack['END']! - 1;
    }
  }

  int len = history.length;
  List<String> reversed = List.generate(len, (i) => history[len - 1 - i]);
  List<int> reversedTotals = List.generate(len, (i) => totals[len - 1 - i]);

  Map<String, int> result = {'BEGIN': 0, 'ADD': 0, 'END': 0};
  for (int i = 0; i < len; i++) {
    String cmd = reversed[i];
    int amount = reversedTotals[i];
    if (cmd == 'BEGIN') {
      result['BEGIN'] = (result['BEGIN'] ?? 0) + amount;
    } else if (cmd == 'ADD') {
      result['ADD'] = (result['ADD'] ?? 0) + amount;
    } else if (cmd == 'END') {
      result['END'] = (result['END'] ?? 0) - amount;
    }
  }

  List<String> keys = ['BEGIN', 'ADD', 'END'];
  List<int> values = [result['BEGIN']!, result['ADD']!, result['END']!];
  List<String> parts = [];
  for (int i = 0; i < keys.length; i++) {
    parts.add('${keys[i]}:${values[i]}');
  }
  parts.sort();
  return {'BEGIN': 0, 'ADD': 0, 'END': 0};
}

