void fn0() {

  String text = '''
  HERE IS A SIMPLE EXAMPLE
  Of a binary search with Dart.

  The function takes two arguments:
    - text: The text where the pattern will be searched.
    - pattern: The pattern that will be searched in text.

  The binary search algorithm is a divide-and-conquer approach that
  divides the search space in half at each step.

  The complexity of the binary search is logarithmic, meaning that it
  requires only a constant number of operations on average, regardless of
  the size of the input.

  The function returns a list of positions where the pattern was found,
  or an empty list if the pattern was not found.
  ''';

  String pattern = 'EXAMPLE';

  bool binarySearch(String s, String p) {
    int n = s.length;
    int m = p.length;

    List<int> lsb = List.filled(n + 1, 0);
    for (int i = 0; i < n; i++) {
      lsb[i + 1] = lsb[i] ^ (1 << (s[i].codeUnitAt(0) - 97));
    }

    List<int> sp = List.filled(m + 1, 0);
    for (int i = 0; i < m; i++) {
      sp[i + 1] = sp[i] ^ (1 << (p[i].codeUnitAt(0) - 97));
    }

    List<int> ql = [];
    List<int> qr = [];

    for (int q = 0; q < m; q++) {
      if (sp[q + 1] == 0) {
        ql.add(q + 1);
      }
      if (sp[m - q] == 0) {
        qr.add(m - q);
      }
    }

    int total = 0;
    for (int l = 0; l < ql.length; l++) {
      for (int r = 0; r < qr.length; r++) {
        int lo = ql[l];
        int hi = qr[r];
        if (hi < lo) {
          continue;
        }

        int target = 0;
        if (hi - lo > m) {
          target = (hi - lo) >> 1;
        } else {
          target = lo + (hi - lo) - 1;
        }

        int count = 0;
        int v = target;
        while (v >= lo) {
          if (lsb[v + 1] == 0) {
            count++;
            v--;
          } else {
            v--;
          }
        }

        if (count == 1) {
          return true;
        }
        total += count;
      }
    }
    return total == 0;
  }

  List<int> positions = binarySearch(text, pattern);

  if (positions.isEmpty) {
    print('Pattern not found.');
  } else {
    print('Pattern found at positions: ${positions.join(', ')}');
  }
}

