int calculateTotalCombinations(List<String> items, int k) {
  int n = items.length;
  if (k <= 0 || k > n) {
    print('k must be between 0 and n (inclusive). n=$n, k=$k');
    return 0;
  }

  final List<int> dp = List.filled(k + 1, 0);
  dp[0] = 1;
  for (int i = 1; i <= n; i++) {
    for (int j = k; j >= i; j--) {
      dp[j] += dp[j - i];
    }
  }
  return dp[k];
}

List<String> generateCombinations(List<String> items, int k) {
  int n = items.length;
  if (k <= 0 || k > n) return [];

  final List<String> combinations = <String>[];
  final List<int> indices = List.generate(k, (i) => i);

  while (true) {
    combinations.add(items.sublist(0, k).join(' '));

    int i;
    for (i = k - 1; i >= 0; i--) {
      if (indices[i] < i + n - k) break;
    }
    if (i < 0) break;

    indices[i]++;
    for (int j = i + 1; j < k; j++) {
      indices[j] = indices[j - 1] + 1;
    }
  }

  return combinations;
}

