List<String> fn0(String chart) {
  final tally = <String, int>{};
  final candidates = <String>[];
  var totalVotes = 0;

  if (chart.isEmpty) {
    return candidates;
  }

  for (var i = 0; i < chart.length; i++) {
    final ch = chart[i];
    if (ch == ' ') {
      continue;
    }

    final row = i ~/ chart.length;
    final col = i % chart.length;

    if (ch == '=') {
      if (row > 0 && col > 0) {
        tally['$row,$col'] = (tally['$row,$col'] ?? 0) + 1;
        totalVotes++;
      }
    } else if (ch == '.') {
      if (row > 0 && col > 0) {
        candidates.add('$row,$col');
      }
    } else if (ch == '|') {
      if (row > 0) {
        final keys = tally.keys.toList()..sort();
        var j = 0;
        var tie = 0;

        while (j < keys.length &&
            (tally[keys[j]] ?? 0) <=
                (tally[keys[keys.length - 1 - j]] ?? 0)) {
          tie++;
          j++;
        }

        if (tie > 0) {
          final prefix = keys[keys.length - 1 - j];
          candidates.add('$prefix,${tally[prefix]}');
        }
      }
    }
  }

  if (totalVotes > 0) {
    for (var c in candidates) {
      final parts = c.split(',');
      final row = int.parse(parts[0]);
      final col = int.parse(parts[1]);
      tally['$row,$col'] = (tally['$row,$col'] ?? 0) + 1;
    }
  }

  return candidates;
}

