    leftStarts.add(int.parse(parts[0]));
    rightStarts.add(int.parse(parts[1]));
    leftLens.add(int.parse(parts[2]));
    rightLens.add(int.parse(parts[3]));
    leftEnds.add(int.parse(parts[0]) + leftLens[leftStarts.length - 1] - 1);
    rightEnds.add(int.parse(parts[1]) + rightLens[rightStarts.length - 1] - 1);
  }

  int maxLeft = 0;
  int minRight = 0;

  for (int i = 0; i < keys.length; i++) {
    int left = leftStarts[i];
    int right = rightStarts[i];
    int lens = leftLens[i];
    int end = leftEnds[i];
    if (end > rightEnds[minRight]) {
      minRight = i;
      maxLeft = left;
    }
  }

  int maxLen = 0;
  if (maxLeft > 0) {
    int mLen = rightEnds[maxLeft] - leftEnds[maxLeft] + 1;
    if (mLen > maxLen) maxLen = mLen;
  }

  result.add(maxLen);
  result.add(maxLeft);
  return result;
}

