  List<int> depths = [];
  List<String> items = [];
  bool open = false;
  String current = '';
  int level = 0;
  Set<String> visited = {};

  for (int i = 0; i < code.length; i++) {
    String ch = code[i];
    if (ch == '!') {
      if (open) {
        if (current.isNotEmpty) {
          runs.add(current);
          items.add(ch);
        }
        open = false;
      }
      current = '';
      level = 0;
    } else if (ch == '[') {
      open = true;
      current = '';
      level = 0;
    } else if (open && ch == ']') {
      open = false;
      current = '';
      level = 0;
    } else if (open && ch == '|') {
      if (current.isNotEmpty) {
        runs.add(current);
        depths.add(level);
      }
      current = '';
      level = 0;
    } else if (open) {
      if (ch == ',') {
        if (current.isNotEmpty) {
          runs.add(current);
          depths.add(level);
        }
        current = '';
        level = 0;
      } else {
        String escaped = '';
        for (int j = 0; j < current.length; j++) {
          if (current[j] == '\\') {
            escaped += '\\';
          } else if (current[j] == '|' || current[j] == '!') {
            escaped += '|';
          } else {
            escaped += current[j];
          }
        }
        current += escaped;
        level++;
      }
    }
  }

  if (open) {
    if (current.isNotEmpty) {
      runs.add(current);
      depths.add(level);
    }
  }

  List<String> keys = [];
  List<String> values = [];

  for (int k = 0; k < runs.length; k++) {
    String key = '${runs[k]}|${depths[k]}';
    if (!visited.contains(key)) {
      visited.add(key);
      keys.add(key);
      values.add(runs[k]);
    }
  }

  keys.sort();

  List<String> result = [];
  for (String key in keys) {
    for (int i = 0; i < values.length; i++) {
      if (values[i] == key.split('|')[0]) {
        result.add(key);
        break;
      }
    }
  }

  return result;
}

