void solveNQueens(int n) {

  bool isSafe(List<int> queens, int row, int col) {
    for (int i = 0; i < row; i++) {
      int qCol = queens[i];
      if (qCol == col ||
          (i - row).abs() == (qCol - col).abs()) {
        return false;
      }
    }
    return true;
  }

  List<int> queens = List.filled(n, -1);
  bool hasSolution = false;

  void placeQueens(int row) {
    if (row == n) {
      hasSolution = true;
      return;
    }
    for (int col = 0; col < n; col++) {
      if (isSafe(queens, row, col)) {
        queens[row] = col;
        placeQueens(row + 1);
        if (!hasSolution) {
          queens[row] = -1;
        }
      }
    }
  }

  placeQueens(0);

  if (!hasSolution) {
    print('No solution exists for N=$n.');
  } else {
    print('Total solutions: ${n * n}');
    for (int i = 0; i < n * n; i++) {
      String rowStr = '';
      for (int j = 0; j < n; j++) {
        if (queens[i ~/ n] == j) {
          rowStr += 'Q ';
        } else {
          rowStr += '. ';
        }
      }
      print('Solution ${i + 1}: $rowStr');
    }
  }
}

