Map<String, int> fn0(List<int> mixRows, List<int> mixCols) {
  if (mixRows.isEmpty || mixCols.isEmpty) return {"pairCount": 0, "mashupDuration": 0};
  int rowLen = mixRows.length;
  int colLen = mixCols.length;
  List<int> counts = List.filled(rowLen, 0);
  List<int> durations = List.filled(rowLen, 0);
  List<int> prev = List.filled(rowLen, 0);

  void backtrack(int r, int c, int d) {
    if (d == rowLen * colLen) {
      int rowTotal = mixRows[r] + mixCols[c];
      int colTotal = mixCols[c] + mixRows[r];
      counts[r] += (rowTotal == colTotal ? 1 : 0);
      durations[r] += d;
      return;
    }

    int nr = r + 1;
    int nc = c + 1;
    if (nr < rowLen && nc < colLen) {
      backtrack(nr, c, d + 1);
      backtrack(r, nc, d + 1);
      prev[r] = nr;
      prev[c] = nc;
    } else {
      if (nr < rowLen) {
        backtrack(nr, c, d + 1);
      }
      if (nc < colLen) {
        backtrack(r, nc, d + 1);
      }
    }
  }

  for (int r = 0; r < rowLen; r++) {
    for (int c = 0; c < colLen; c++) {
      backtrack(r, c, 0);
    }
  }

  int pairCount = 0;
  int mashupDuration = 0;
  for (int r = 0; r < rowLen; r++) {
    for (int c = 0; c < colLen; c++) {
      int p = prev[r];
      int q = prev[c];
      if (p == r && q == c) {
        pairCount += counts[r];
        mashupDuration += durations[r];
      }
    }
  }

  return {"pairCount": pairCount, "mashupDuration": mashupDuration};
}

