Map<String, int> fn0(List<int> durations) {
  if (durations.isEmpty) return {'pairCount': 0, 'mashupDuration': 0};
  int n = durations.length;
  int left = 0;
  int right = n - 1;
  int mask = 0;
  while (left <= right) {
    int mid = (left + right) ~/ 2;
    int oddCount = 0;
    int evenCount = 0;
    int oddSum = 0;
    int evenSum = 0;
    for (int i = 0; i < n; i++) {
      if (i >= mid) {
        mask |= 1 << (i - mid);
      }
      if ((mask & (1 << (i - mid))) != 0) {
        oddCount++;
        oddSum += durations[i];
      } else {
        evenCount++;
        evenSum += durations[i];
      }
    }
    if (oddCount == evenCount) {
      int pairCount = 0;
      for (int i = 0; i < n; i++) {
        if ((mask & (1 << (i - mid))) != 0) {
          pairCount++;
        }
      }
      int mashupDuration = oddSum > evenSum ? oddSum : evenSum;
      return {'pairCount': pairCount, 'mashupDuration': mashupDuration};
    } else if (oddCount > evenCount) {
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }
  return {'pairCount': 0, 'mashupDuration': 0};
}

