    return {'pairCount': 0, 'mashupDuration': 0};
  }
  int n = songLengths.length;
  if (n == 1) {
    return {'pairCount': 0, 'mashupDuration': songLengths[0]};
  }
  int minLen = songLengths[0];
  int maxLen = songLengths[0];
  for (int i = 1; i < n; i++) {
    if (songLengths[i] < minLen) minLen = songLengths[i];
    if (songLengths[i] > maxLen) maxLen = songLengths[i];
  }
  if (maxLen - minLen == 0) {
    return {'pairCount': n, 'mashupDuration': songLengths[0]};
  }
  Map<int, List<int>> prefixSums = {};
  for (int i = 0; i < n; i++) {
    prefixSums[i] = [songLengths[i]];
  }
  for (int i = 1; i < n; i++) {
    for (int j = 0; j < i; j++) {
      int len = songLengths[i] + songLengths[j];
      if (len >= minLen && len <= maxLen) {
        prefixSums[i]!.add(len);
      }
    }
  }
  int pairCount = 0;
  int mashupDuration = 0;
  for (int i = 0; i < n; i++) {
    for (int len in prefixSums[i]!) {
      pairCount++;
      mashupDuration += len;
    }
  }
  return {'pairCount': pairCount, 'mashupDuration': mashupDuration};
}

