Map<String, int> fn0(List<int> heights) {
  int n = heights.length;
  if (n < 2) return {"pairCount": 0, "mashupDuration": 0};

  int findMaximalPair(int left, int right) {
    while (left < right) {
      int mid = (left + right) ~/ 2;
      if (heights[mid] > heights[right]) {
        right = mid;
      } else {
        left = mid + 1;
      }
    }
    return left;
  }

  int binarySearch(int value) {
    int left = 0;
    int right = n - 1;
    while (left <= right) {
      int mid = (left + right) ~/ 2;
      if (heights[mid] == value) {
        return mid;
      } else if (heights[mid] < value) {
        left = mid + 1;
      } else {
        right = mid - 1;
      }
    }
    return -1;
  }

  int bestLeft = findMaximalPair(0, n - 1);
  int bestRight = findMaximalPair(0, n - 1);
  int bestDuration = 0;
  int maxDuration = 0;

  for (int left = 0; left <= n - 1; left++) {
    for (int right = left; right <= n - 1; right++) {
      int duration = right - left + 1;
      if (duration > maxDuration) {
        maxDuration = duration;
        bestLeft = left;
        bestRight = right;
      }

      int lh = binarySearch(heights[left]);
      int rh = binarySearch(heights[right]);
      if (lh > -1 && rh > -1) {
        int overlap = rh - lh + 1;
        if (overlap > duration) {
          duration = overlap;
        }
      }
    }
  }

  return {"pairCount": bestRight - bestLeft + 1, "mashupDuration": maxDuration};
}

