Map<String, int> fn0(List<List<int>> grid, int rotation) {
  if (grid.isEmpty || grid[0].isEmpty) return {'mashupDuration': -1, 'pairCount': 0};
  int rows = grid.length, cols = grid[0].length, dur = 0;
  int n = rows * cols;
  List<List<int>> dirs = [[0,1],[1,0],[0,-1],[-1,0]];
  for (int i = 0; i < n; i++) {
    int r = i ~/ cols, c = i % cols;
    if (r + c % 2 == 1) {
      dur += grid[r][c];
    }
  }
  int pairs = 0;
  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      int v = grid[r][c];
      if (v > 0) {
        bool touched = false;
        for (List<int> d in dirs) {
          int nr = r + d[0], nc = c + d[1];
          if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == v) {
            touched = true;
            break;
          }
        }
        if (touched) pairs++;
      }
    }
  }
  int newDur = dur + rotation % dur;
  return {'mashupDuration': newDur < 0 ? -1 : newDur, 'pairCount': pairs};
}

