import 'dart:math';

class Quaternion {
  double x, y, z, w;
  Quaternion(this.x, this.y, this.z, this.w);

  Quaternion operator +(Quaternion other) {
    return Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);
  }

  Quaternion operator -(Quaternion other) {
    return Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);
  }

  Quaternion operator *(double scalar) {
    return Quaternion(x * scalar, y * scalar, z * scalar, w * scalar);
  }

  Quaternion operator *(Quaternion other) {
    double xt = x * other.w - other.x * w;
    double ytt = y * other.w + other.y * w;
    double ztt = z * other.w - other.z * w;
    double wtt = x * other.y - y * other.x + z * other.z;
    return Quaternion(xt, ytt, ztt, wtt);
  }

  Quaternion inverse() {
    double x1 = x * x + y * y + z * z + w * w;
    double inv = 1 / x1;
    return Quaternion(-x * inv, -y * inv, -z * inv, -w * inv);
  }

  Quaternion normalized() {
    double norm = x * x + y * y + z * z + w * w;
    double inv = 1 / norm;
    return Quaternion(x * inv, y * inv, z * inv, w * inv);
  }

  Quaternion conjugate() {
    return Quaternion(x, y, z, -w);
  }

  double norm() {
    return x * x + y * y + z * z + w * w;
  }

  String toString() {
    String parts = "$x + $y*i + $z*j + $w*k";
    return parts;
  }
}

