class Quaternion {
  final double x, y, z, w;
  final double norm;

  const Quaternion._internal(this.x, this.y, this.z, this.w);

  factory Quaternion(List<double> components) {
    double x = components[0];
    double y = components[1];
    double z = components[2];
    double w = components[3];
    return Quaternion._internal(x, y, z, w);
  }

  const Quaternion(this.x, this.y, this.z, this.w);

  const Quaternion.unit => const Quaternion(0, 0, 0, 1);

  const Quaternion.zero => const Quaternion(0, 0, 0, 0);

  const Quaternion.negative => const Quaternion(-x, -y, -z, -w);

  const Quaternion.inverse => const Quaternion(x, y, z, 1 / w);

  const Quaternion.rotation(double angle, Vector3 axis) {
    double sin = sin(angle);
    double cos = cos(angle);
    return Quaternion(
        x * cos - y * sin * axis.x,
        y * cos + x * sin * axis.y,
        z * cos - w * sin * axis.z,
        w * cos + x * sin * axis.z);
  }

  const Quaternion.fromAxisAngle(Vector3 axis, double angle) {
    double sin = sin(angle);
    double cos = cos(angle);
    return Quaternion(
        x * cos - y * sin * axis.x,
        y * cos + x * sin * axis.y,
        z * cos - w * sin * axis.z,
        w * cos + x * sin * axis.z);
  }

  const Quaternion.fromBasis(Vector3 v1, Vector3 v2) {
    double l1 = v1.length;
    double l2 = v2.length;
    if (l1 == 0 || l2 == 0) return const Quaternion.zero;
    double a = l1 < l2 ? l1 : l2;
    double b = l1 < l2 ? l2 : l1;
    double x = v1.x * v2.y - v1.y * v2.x;
    double y = v1.x * v2.z + v1.z * v2.x;
    double z = v1.y * v2.z - v1.z * v2.y;
    double w = (v1.x * v2.x + v1.y * v2.y + v1.z * v2.z) / (2 * a * b);
    return Quaternion(x * 2 * w, y * 2 * w, z * 2 * w, a * (1 - 2 * w * w));
  }

  const Quaternion.normalized => const Quaternion(x / norm, y / norm, z / norm, w / norm);

  const Quaternion operator +(const other) => const Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);

  const Quaternion operator -(const other) => const Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);

  const Quaternion operator *(const other) {
    double a = x, b = y, c = z, d = w;
    double e = other.x, f = other.y, g = other.z, h = other.w;
    return const Quaternion(
        d * e - a * g - b * h + c * f,
        a * f + d * c + b * g - e * h,
        b * e - c * g + d * f + a * h,
        a * b * c * d);
  }

  const Quaternion operator ^(const other) => const Quaternion(x * other.w - y * other.z - z * other.y + w * other.x,
      y * other.w + x * other.z + z * other.y - w * other.x,
      z * other.w - w * other.x - x * other.y + y * other.z,
      w * other.w + x * y * z - a * b * c);

  const Quaternion conjugate => const Quaternion(x, y, z, w);

  const Quaternion inverse => const Quaternion(x, y, z, 1 / w);

  const Quaternion rotate(Vector3 axis, double angle) => const Quaternion.rotation(angle, axis);

  const Quaternion normalize => const Quaternion.normalized;

  const double norm => sqrt(x * x + y * y + z * z + w * w);

  @override
  bool operator ==(Object other) {
    if (other is Quaternion) {
      return x == other.x && y == other.y && z == other.z && w == other.w;
    }
    return false;
  }

  @override
  int get hashCode => x.hashCode ^ y.hashCode ^ z.hashCode ^ w.hashCode;

  @override
  String toString() => 'q1 = $x + $y * i + $z * j + $w * k';
}

