    this.imag1 = 0.0,
    this.imag2 = 0.0,
    this.imag3 = 0.0,
  }) {
    double norm = real.abs() + imag1.abs() + imag2.abs() + imag3.abs();
    real /= norm;
    imag1 /= norm;
    imag2 /= norm;
    imag3 /= norm;
  }

  const Quaternion.conjugate(this.real, {
    this.imag1 = imag1,
    this.imag2 = imag2,
    this.imag3 = imag3,
  }) {
