class Quaternion {
  final double x;
  final double y;
  final double z;
  final double w;

  const Quaternion(this.x, this.y, this.z, this.w);

  const Quaternion.zero() : this(0.0, 0.0, 0.0, 0.0);

  const Quaternion.unit() : this(0.0, 0.0, 0.0, 1.0);

  const Quaternion.random() : this(
      Random(0).nextDouble() * 2 - 1,
      Random(0).nextDouble() * 2 - 1,
      Random(0).nextDouble() * 2 - 1,
      Random(0).nextDouble() * 2 - 1);

  const Quaternion.normalized(this.x, this.y, this.z, this.w)
      : this(x / norm(), y / norm(), z / norm(), w / norm());

  const Quaternion.operator_+(other) : this(x + other.x, y + other.y, z + other.z, w + other.w);

  const Quaternion.operator_-(other) : this(x - other.x, y - other.y, z - other.z, w - other.w);

  const Quaternion.operator_*(other) : this(x * other.x - y * other.y - z * other.z + w * other.w,
      x * other.y + y * other.x + z * other.w - w * other.z,
      x * other.z - y * other.w + z * other.x + w * other.y);

  const Quaternion.operator_*(num scalar) : this(x * scalar, y * scalar, z * scalar, w * scalar);

  const Quaternion.inverse() : this(x, y, z, -w);

  const Quaternion.rotate(
      this.x, this.y, this.z, this.w,
      num angle,
      [bool isDegrees = true, Axis axis = Axis.z, Origin origin = Origin.center]) {
    if (angle == 0.0) return this;
    final double s = sin(angle / 2);
    final double c = cos(angle / 2);
    switch (axis) {
      case Axis.x:
        final double px = x * c - y * s;
        final double py = x * s + y * c;
        final double pz = z;
        final double pw = w;
        return this + Quaternion(px, py, pz, pw);
      case Axis.y:
        final double py = y * c - z * s;
        final double pz = y * s + z * c;
        final double pw = w;
        return this + Quaternion(x, py, pz, pw);
      case Axis.z:
        final double pz = z * c - x * s;
        final double pw = z * s + x * c;
        return this + Quaternion(x, y, pz, pw);
    }
  }

  const Quaternion.conjugate() : this(x, y, z, -w);

  const double norm() => x * x + y * y + z * z + w * w;

  @override
  String toString() => '$x + $y*i + $z*j + $w*k';
}

