class Quaternion {
  double x = 0.0, y = 0.0, z = 0.0, w = 0.0;

  Quaternion(this.x, this.y, this.z, this.w);

  Quaternion.unit(double angle) {
    w = 1.0;
    x = 0.5 * angle * 2;
    y = 0.5 * angle * 2;
    z = 0.5 * angle * 2;
  }

  Quaternion.zero() : this(0.0, 0.0, 0.0, 0.0);

  Quaternion.forward(double angle) {
    w = 1.0;
    x = angle;
    y = 0.0;
    z = 0.0;
  }

  Quaternion.backward(double angle) {
    w = 1.0;
    x = -angle;
    y = 0.0;
    z = 0.0;
  }

  Quaternion.up(double angle) {
    w = 1.0;
    x = 0.0;
    y = angle;
    z = 0.0;
  }

  Quaternion.down(double angle) {
    w = 1.0;
    x = 0.0;
    y = -angle;
    z = 0.0;
  }

  Quaternion.right(double angle) {
    w = 1.0;
    x = angle;
    y = 0.0;
    z = 0.0;
  }

  Quaternion.left(double angle) {
    w = 1.0;
    x = -angle;
    y = 0.0;
    z = 0.0;
  }

  Quaternion.aroundZ(double angle) {
    w = 1.0;
    x = angle * 0.5;
    y = -angle * 0.5;
    z = angle;
  }

  Quaternion.aroundY(double angle) {
    w = 1.0;
    x = -angle * 0.5;
    y = angle;
    z = angle * 0.5;
  }

  Quaternion.aroundX(double angle) {
    w = 1.0;
    x = angle;
    y = -angle * 0.5;
    z = angle * 0.5;
  }

  Quaternion.fromAxisAngle(List<double> axis, double angle) {
    double ax = axis[0], ay = axis[1], az = axis[2];
    w = cos(angle / 2);
    x = ax * sin(angle / 2);
    y = ay * sin(angle / 2);
    z = az * sin(angle / 2);
  }

  Quaternion.fromBasisVectors(List<double> v1, List<double> v2) {
    double a1x = v1[0], a1y = v1[1], a1z = v1[2];
    double b1x = v2[0], b1y = v2[1], b1z = v2[2];
    w = (a1x * b1y - a1y * b1x + a1z * b1z - b1z * a1y + b1y * a1z - b1z * a1x) / 2.0;
    x = (a1y * b1z - a1z * b1y + b1z * a1x) / 2.0;
    y = (a1z * b1x - a1x * b1z + b1z * a1y) / 2.0;
    z = (a1x * b1y - a1y * b1x + a1z * b1z - b1z * a1y + b1y * a1z - b1z * a1x) / 2.0;
  }

  double norm() {
    return sqrt(x * x + y * y + z * z + w * w);
  }

  Quaternion conjugate() {
    return Quaternion(x, y, z, -w);
  }

  Quaternion inverse() {
    double n = norm();
    if (n == 0) {
      throw ArgumentError('Cannot invert zero quaternion');
    }
    return Quaternion(x / n, y / n, z / n, w / n);
  }

  Quaternion normalized() {
    double n = norm();
    if (n == 0) {
      throw ArgumentError('Cannot normalize zero quaternion');
    }
    return Quaternion(x / n, y / n, z / n, w / n);
  }

  Quaternion operator +(other) {
    return Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);
  }

  Quaternion operator -(other) {
    return Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);
  }

  Quaternion operator *(other) {
    double ax = x, ay = y, az = z, aw = w;
    double bx = other.x, by = other.y, bz = other.z, bw = other.w;
    return Quaternion(
      ax * other.w + bx * aw,
      ay * other.w + by * aw,
      az * other.w + bz * aw,
      aw * other.w + bw * bx,
    );
  }

  @override
  bool operator ==(other) {
    return x == other.x &&
        y == other.y &&
        z == other.z &&
        w == other.w;
  }

  @override
  int get hashCode => x.hashCode ^ y.hashCode ^ z.hashCode ^ w.hashCode;

  @override
  String toString() {
    return 'q1 = $x + $y * i + $z * j + $w * k';
  }
}

