  for (int i = 0; i < n; i += 4) {
    int week = schedule[i];
    int day = schedule[i + 1];
    int start = schedule[i + 2];
    int duration = schedule[i + 3];

    if (day < 1 || day > 7 || duration < 0) return false;
    if (day + duration > 7) return false;

    if (week == 1 || week == 7) {
      if (day < start) return false;
      if (day + duration > start + 6) return false;
    } else if (week == 2 || week == 3) {
      if (day > start) return false;
      if (day + duration < start + 2) return false;
    } else if (week == 4 || week == 5) {
      if (day > start) return false;
      if (day + duration < start + 5) return false;
    } else if (week == 6 || week == 0) {
      if (day < start) return false;
      if (day + duration > start + 10) return false;
    }
  }

  for (int i = 0; i < n; i += 4) {
    int prevWeek = -1;
    for (int j = i; j < i + 4; j++) {
      int week = schedule[j];
      if (week < 1 || week > 7) return false;
      if (prevWeek != -1 && week != prevWeek) cycleLength++;
      prevWeek = week;
    }
  }

  if (cycleLength < 2) return false;
  if (cycleLength > 6) return false;

  for (int i = 1; i < cycleLength; i++) {
    bool found = false;
    for (int j = i; j < cycleLength; j++) {
      if (schedule[i * 4] == schedule[j * 4]) {
        found = true;
        break;
      }
    }
    if (!found) return false;
  }

  return true;
}

