  }
  List<String> tokens = log.split(',');
  for (String token in tokens) {
    String trimmed = token.trim();
    if (trimmed.isEmpty) {
      continue;
    }
    String op = trimmed.split(' ')[0];
    if (op != '!' && op != '=') {
      continue;
    }
    if (op == '=') {
      int colon = trimmed.indexOf(':');
      if (colon < 1 || colon != trimmed.length - 2) {
        continue;
      }
      String packetIdStr = trimmed.substring(1, colon);
      String sizeStr = trimmed.substring(colon + 1);
      if (packetSizes.containsKey(packetIdStr)) {
        int current = packetSizes[packetIdStr]!;
        int newSize = int.tryParse(sizeStr) ?? -1;
        if (newSize >= 0) {
          packetSizes[packetIdStr] = current + newSize;
        }
      } else {
        packetSizes[packetIdStr] = int.tryParse(sizeStr) ?? -1;
      }
    } else if (op == '!') {
      int colon = trimmed.indexOf(':');
      if (colon < 1 || colon != trimmed.length - 2) {
        continue;
      }
      String packetIdStr = trimmed.substring(1, colon);
      String sizeStr = trimmed.substring(colon + 1);
      int? current = packetSizes[packetIdStr];
      if (current != null && int.tryParse(sizeStr) != null) {
        packetSizes[packetIdStr] = current! + int.tryParse(sizeStr)!;
      }
    }
  }
  return packetSizes;
}

