Map<String, int> fn0(List<int> positions, int interval) {
  int gcd(int a, int b) {
    while (b != 0) {
      final t = a % b;
      a = b;
      b = t;
    }
    return a;
  }

  int cycleCount = 0;
  int uniquePositions = 0;

  for (int i = 0; i < positions.length; i++) {
    final pos = positions[i] % interval;
    final posAbs = pos.abs();
    if (posAbs == 0) {
      cycleCount += 2;
      uniquePositions++;
      continue;
    }
    if (gcd(posAbs, interval) != 1) {
      continue;
    }

    bool repeated = false;
    for (int j = 0; j < i; j++) {
      final p2 = positions[j] % interval;
      final p2Abs = p2.abs();
      if (p2Abs == 0) {
        cycleCount += 2;
        uniquePositions++;
        continue;
