      if (p2Abs == posAbs) {
        repeated = true;
        break;
      }
    }
    if (repeated) {
      continue;
    }

    final period = gcd(posAbs, interval);
    for (int k = 0; k < period; k++) {
      if (pos == p2) {
        cycleCount++;
        uniquePositions--;
        break;
      }
      if (k == 0 || k == period - 1) {
        cycleCount += 2;
        uniquePositions++;
      }
    }
  }

  return {
    'gcd': gcd(uniquePositions, cycleCount),
    'cycleCount': cycleCount,
    'uniquePositions': uniquePositions,
