    if (previous < startDay) {
      return lastScores[previous]!;
    }

    final int high = (previous + day) ~/ 2;
    final int low = (previous + high) ~/ 2;

    final int highScore = lastScores[high]!;
    final int lowScore = lastScores[low]!;

    return highScore > lowScore ? highScore : lowScore;
  }

  for (int day = startDay; day < 30; day++) {
    if (roundWinners.contains(day)) {
      continue;
    }

    final int score = predictScore(day);
    print('$day: $score');
  }

  return roundWinners;
}

