enum HostSystem {

  littleEndian,

  bigEndian,

  detected(HostSystem.littleEndian),

  none() {

    return null;
  }

  final HostSystem _type;

  const HostSystem(this._type);

  static HostSystem detect() {

    int data = 0x12345678;

    if (((data & 0xFFFFFFFF) == 0x12345678) != ((data >> 32) & 0xFFFFFFFF) == 0x12345678) {
      return HostSystem.bigEndian;
    }

    return HostSystem.littleEndian;
  }

  String get name {
    return _type.name;
  }

  bool get isLittleEndian => _type == HostSystem.littleEndian;

  bool get isBigEndian => _type == HostSystem.bigEndian;

  bool get isDetected => _type == HostSystem.detected;

  bool get isNone => _type == HostSystem.none;
}

