  bool checkPermission(String user, String resource, String action) {
    if (!resourceAccess.containsKey(resource)) {
      return false;
    }
    if (!userPermissions.containsKey(user)) {
      return false;
    }
    List<String> requiredRoles = resourceAccess[resource]!;
    List<String> availableRoles = userPermissions[user]!;

    for (String role in requiredRoles) {
      if (availableRoles.contains(role)) {
        List<String> permissions = permissions[role]!;
        return permissions.contains(action);
      }
    }
    return false;
  }

  bool checkPermissionInheritance(String user, String resource, String action) {
    if (!resourceAccess.containsKey(resource)) {
      return false;
    }
    if (!userPermissions.containsKey(user)) {
      return false;
    }
    List<String> requiredRoles = resourceAccess[resource]!;
    List<String> availableRoles = userPermissions[user]!;

    for (String role in requiredRoles) {
      if (availableRoles.contains(role)) {
        Map<String, List<String>> inherited = roles[role]!;
        if (inherited.containsKey(user)) {
          List<String> inheritedPermissions = inherited[user]!;
          if (inheritedPermissions.contains(action)) {
            return true;
          }
        }
      }
    }
    return false;
  }

