bool checkAccess(String resource, String action, String user, String role) {

  Map<String, Map<String, int>> rolePermissions = {
    'admin': {
      'read': 1,
      'write': 1,
      'delete': 1,
      'admin': 1,
    },
    'moderator': {
      'read': 1,
      'write': 1,
      'delete': 1,
    },
    'editor': {
      'read': 1,
      'write': 1,
    },
    'viewer': {
      'read': 1,
    },
  };

  Map<String, List<String>> resourceAccess = {
    'document1': ['read', 'write'],
    'document2': ['read', 'delete'],
    'sensitive_data': ['read', 'write', 'delete'],
    'admin': ['read', 'write', 'delete', 'admin'],
  };

  String currentRole = role;

  if (!resourceAccess.containsKey(resource)) {
    print('  ➜ Resource not found');
    return false;
  }

  if (!rolePermissions.containsKey(currentRole)) {
    print('  ➜ Unknown role: $currentRole');
    return false;
  }

  if (!resourceAccess[resource]!.contains(action)) {
    print('  ➜ Access DENIED (Insufficient permissions)');
    return false;
  }

  if (currentRole == 'admin' || resource == 'admin') {
    return true;
  }

  if (resource == 'admin') {

    Map<String, String> nestedRoles = {
      'alice': 'admin',
      'bob': 'editor',
      'charlie': 'viewer',
    };
    String nestedRole = nestedRoles[user] ?? 'viewer';
    if (rolePermissions[nestedRole]!.contains(action)) {
      return true;
    }
  }

  return false;
}

