List<int> floatToNetwork(double value) {
  int sign = value < 0 ? 1 : 0;
  value = value.abs();

  int fraction = value * 256.0;
  int intPart = (fraction).floor();
  double fracPart = fraction - intPart;

  int exponent = (fracPart * 127).round();

  int packed = ((sign << 31) | (intPart << 16) | (exponent << 8) | (fracPart * 127)) & 0xFFFFFFFF;
  return [packed >> 16, packed & 0xFFFF];
}

