      bigEnd = temp & 0xFF;
      temp >>= 8;
    } while (temp != 0);
    do {
      littleEnd = temp & 0xFF;
      temp >>= 8;
    } while (temp != 0);
    return (bigEnd < littleEnd) ? bigEnd : littleEnd;
  }

  int hostByteOrder(int value) {
    int host = value & 0xFFFFFFFF;
    int bigEnd = 0;
    int littleEnd = 0;
    int temp = host;
