    }
  }

  Map<int, int> freq = {};
  for (var t in transactions) {
    Map<int, int> itemCount = {};
    for (int i = 0; i < t.length; i++) {
      int idx = t[i];
      itemCount[idx] = (itemCount[idx] ?? 0) + 1;
    }
