      for (var item in t) {
        int idx = item;
        freq[idx] = (freq[idx] ?? 0) + 1;
      }
    }
  }

  Set<int> frequentItemsets = {};
  frequentItemsets.addAll(itemSet);

  List<int> candidateSet = [itemSet];
