  void generateAssociationRules(List<Map<int, int>> frequentItemsets) {
    Map<int, List<Map<int, int>>> frequentItemsetsWithSupport = {};
    for (var itemset in frequentItemsets) {
      int support = itemset.values.reduce((a, b) => a + b);
      frequentItemsetsWithSupport[support] ??= [];
      frequentItemsetsWithSupport[support]!.add(itemset);
    }

    List<List<int>> rulePairs = [];
    for (var entry in frequentItemsetsWithSupport.entries) {
      List<Map<int, int>> itemsets = entry.value;
      if (itemsets.length >= 2) {
        for (int i = 0; i < itemsets.length - 1; i++) {
          for (int j = 0; j < itemsets.length - 1 - i; j++) {
            List<int> left = itemsets[i];
            List<int> right = itemsets[j + 1];

            if (left.isNotEmpty && right.isNotEmpty && left.length <= right.length) {
              bool leftExistsInRight = false;
              for (var item in left) {
                if (!right.contains(item)) break;
                leftExistsInRight = true;
              }
              if (leftExistsInRight) {
                rulePairs.add([left, right, entry.key]);
              }
            }
          }
        }
      }
    }

    rulePairs.sort((a, b) {
      if (a[0].length != b[0].length) return a[0].length.compareTo(b[0].length);
      if (a[1].length != b[1].length) return a[1].length.compareTo(b[1].length);
      return a[2].compareTo(b[2]);
    });

    print('Frequent Itemsets:');
    for (var itemset in frequentItemsets) {
      double support = itemset.values.reduce((a, b) => a + b) / n;
      print('${itemset.toList()} (support: $support)');
    }
    print('\nAssociation Rules:');
    for (var [left, right, support] in rulePairs) {
      double confidence = support / left.length;
      print('${left.toList()} -> ${right.toList()} (support: $support, confidence: $confidence)');
    }
  }

  generateAssociationRules(frequentItemsetsList);
}

