List<int> fn0(List<int> votes, int threshold) {
  if (votes.isEmpty || threshold < 0) return [];
  int n = votes.length;
  List<int> dp = List.filled(n + 1, 0);
  for (int i = 1; i <= n; i++) {
    List<int> sub = votes.sublist(i - n, i).toList();
    int count = 0, maj = 0;
    for (int v in sub) {
      if (v >= threshold) {
        count++;
        maj = v;
      }
    }
    if (count > 1) {
      dp[i] = dp[i - n] + (maj == sub[0] ? 1 : -1);
    } else {
      dp[i] = maj >= threshold ? 1 : -1;
    }
  }
  return dp;
}

