  }

  final int highestPriorityRow = ranges.first['index']!;
  final int lowestPriorityRow = ranges.last['index']!;
  final int rowsNeedingReview =
      n - (highestPriorityRow + 1) + (lowestPriorityRow - 1) + 1;

