  Rectangle(this.x, this.y, this.width, this.height);

  bool contains(Point p) =>
      p.x >= x && p.x < x + width && p.y >= y && p.y < y + height;

  bool intersects(Rectangle other) =>
      !other.contains(Point(x, y)) &&
      !other.contains(Point(x + width, y)) &&
      !other.contains(Point(x, y + height)) &&
      !other.contains(Point(x + width, y + height));

  Rectangle union(Rectangle other) =>
      Rectangle(min(x, other.x), min(y, other.y),
          max(x + width, other.x + other.width),
          max(y + height, other.y + other.height));

  Rectangle intersection(Rectangle other) {
    double left = x > other.x ? x : other.x;
    double right = x + width < other.x + other.width
        ? x + width
        : other.x + other.width;
    double bottom = y > other.y ? y : other.y;
    double top = y + height < other.y + other.height
        ? y + height
        : other.y + other.height;
    return Rectangle(left, bottom, right - left, top - bottom);
  }

  @override
  String toString() => 'Rectangle($x, $y, $width, $height)';
}

