void fn0() {

  final rand = Random(0);

  final points = [
    [1.0, 2.0],
    [1.5, 2.5],
    [3.0, 3.0],
    [4.0, 4.0],
    [2.0, 2.5],
    [3.5, 4.5],
    [1.0, 4.0],
    [2.5, 5.0],
    [4.5, 7.0],
  ];

  final int k = 3; 
  final double eps = 0.5; 
  final int maxIterations = 100;

  final pointsSet = points.toSet();
  final int n = points.length;

  final clusters = List.generate(n, (_) => List.filled(k, 0));

  int clusterCount = k;

  bool isConverged = false;

  for (int iter = 0; iter < maxIterations && !isConverged; iter++) {

    final newClusters = List.generate(n, (_) => List.filled(k, 0));

    final validIndices = List.generate(n, (_) => List.filled(k, 0));

    for (int i = 0; i < n; i++) {
      double minDist = double.infinity;
      int bestCluster = 0;

      for (int c = 0; c < k; c++) {
        final p = points[i];
        for (int j = 0; j < n; j++) {
          if (points[j] == p && clusters[j][c] == 1) {
            final d = (i - j).abs();
            if (d < minDist) {
              minDist = d;
              bestCluster = c;
            }
          }
        }
      }

      for (int c = 0; c < k; c++) {
        if (c == bestCluster) {
          validIndices[i][c] = 1;
        }
      }

      newClusters[i][bestCluster]++;
    }

    int totalChange = 0;

    for (int c = 0; c < k; c++) {
      int sum = 0;
      for (int i = 0; i < n; i++) {
        if (validIndices[i][c] == 1) {
          sum += clusters[i][c];
        }
      }
      newClusters[c][c] = sum;

      if (newClusters[c][c] != clusters[c][c]) {
        totalChange++;
      }
    }

    if (totalChange == 0) {
      isConverged = true;
    }

    for (int c = 0; c < k; c++) {
      clusters[c] = List.from(newClusters[c]);
    }
  }

  if (isConverged) {
    print('Converged in $iter iteration(s).');
  }

  print('Cluster ${clusterCount}  Points: ${pointsSet.toList()} centroid: ${pointsSet.toList()}');
}

