  int cols = maze[0].length;
  List<List<int>> dist = List.generate(rows, (_) => List.filled(cols, 999999));
  List<List<int>> q = <List<int>>[];
  Set<int> queue = {};
  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (maze[r][c] == '#') continue;
      dist[r][c] = 0;
