  for (int i = 0; i < n; i++) {
    int j = i;
    while (j < n - 1 && moistureGrid[j] == moistureGrid[j + 1]) {
      j++;
    }
    int len = j - i;
    if (len > limit) continue;
    int lo = 0, hi = len - 1, base = moistureGrid[i];
    while (lo <= hi) {
      int mid = (lo + hi) ~/ 2;
      int expected = base + mid * 2;
      if (moistureGrid[i + mid] == expected) {
        if (mid > maxLen) maxLen = mid;
        hi = mid - 1;
      } else if (moistureGrid[i + mid] < expected) {
        lo = mid + 1;
      } else {
        hi = mid - 1;
      }
    }
  }
  return maxLen;
}

